def main(path):
    total = skipped = 0
    try:
        with open(path) as f:
            for line in f:
                try:
                    total += int(line)
                except ValueError:
                    skipped += 1
    except FileNotFoundError:
        print(f"no such file: {path}")
        return 1
    print(total, skipped)
