import { readFile } from 'node:fs/promises';

async function main(path) {
  let text;
  try {
    text = await readFile(path, 'utf8');
  } catch {
    console.log(`no such file: ${path}`);
    return 1;
  }
  let total = 0, skipped = 0;
  for (const line of text.split('\n')) {
    const n = Number(line);
    if (line.trim() === '' || !Number.isInteger(n)) { skipped++; continue; }
    total += n;
  }
  console.log(total, skipped);
  return 0;
}

process.exit(await main(process.argv[2]));

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	f, err := os.Open(os.Args[1])
	if err != nil {
		fmt.Printf("no such file: %s\n", os.Args[1])
		os.Exit(1)
	}
	defer f.Close()

	total, skipped := 0, 0
	s := bufio.NewScanner(f)
	for s.Scan() {
		n, err := strconv.Atoi(s.Text())
		if err != nil {
			skipped++
			continue
		}
		total += n
	}
	fmt.Println(total, skipped)
}
